#!/usr/bin/env python3
"""Offline ADB and usbmuxd/sync wire adapters plus probe certificates.

Only *open* application payloads reach these parsers.  Malformed wire data is
not a record failure: it makes the service state unknown and counts one
protocol error for the responsible latest-attempt row identity.
"""
import base64
import io
import plistlib
import struct
from xml.parsers.expat import ExpatError

MAX_BODY = 65535
MAX_FRAME = 65532
ADB_HEADER = 24
ADB_CNXN = 0x4e584e43
ADB_AUTH = 0x48545541
ADB_CLSE = 0x45534c43
ADB_MAGIC_MASK = 0xffffffff
ADB_HOST_BANNER = b'host::zgrab2'
SYNC_KEYS = ('ProductVersion', 'ProductName')
PLIST_FIELDS = frozenset(('Key', 'Request', 'Value'))
SEND_FIELDS = ('Key', 'Label', 'ProtocolVersion', 'Request')


def checksum(data):
    total = 0
    for byte in data:
        total = (total + byte) & 0xffffffff
    return total


def adb_packet(command, arg0, arg1, body):
    """One little-endian ADB message with a valid length, checksum and magic."""
    return struct.pack('<6I', command, arg0, arg1, len(body),
                       checksum(body), command ^ ADB_MAGIC_MASK) + body


def read_adb_packet(data):
    """Split one exact ADB message, or raise ValueError for bad wire data."""
    if len(data) < ADB_HEADER:
        raise ValueError('short ADB header')
    command, arg0, arg1, length, check, magic = struct.unpack('<6I', data[:ADB_HEADER])
    if command ^ magic != ADB_MAGIC_MASK:
        raise ValueError('bad ADB magic')
    if length > MAX_BODY:
        raise ValueError('ADB length too large')
    body = data[ADB_HEADER:]
    if len(body) != length:
        raise ValueError('ADB body length mismatch')
    if checksum(body) != check:
        raise ValueError('ADB checksum mismatch')
    return command, arg0, arg1, body


def read_adb_response(data):
    """Signature of a CNXN or AUTH open packet; other commands are malformed."""
    command, arg0, arg1, body = read_adb_packet(data)
    if command == ADB_CNXN:
        banner = body.decode('utf-8')
        version = '%d.%d.%d' % ((arg0 >> 16) & 0xff, (arg0 >> 8) & 0xff, arg0 & 0xff)
        return ('CNXN', version, banner)
    if command == ADB_AUTH:
        return ('AUTH', arg0, arg1, bytes(body))
    raise ValueError('unsupported ADB command')


def send_connect():
    return adb_packet(ADB_CNXN, 0x01000000, 4096, ADB_HOST_BANNER)


def send_close():
    return adb_packet(ADB_CLSE, 0, 0, b'')


def get_value_request(key):
    """One length-prefixed usbmuxd GetValue frame."""
    value = plistlib.dumps({'Key': key, 'Label': 'usbmuxd',
                            'ProtocolVersion': '2', 'Request': 'GetValue'},
                           fmt=plistlib.FMT_XML, sort_keys=False)
    if not 1 <= len(value) <= MAX_FRAME:
        raise ValueError('plist frame length out of range')
    return struct.pack('>I', len(value)) + value


def read_plist_frame(stream, key):
    header = stream.read(4)
    if len(header) != 4:
        raise ValueError('short plist frame header')
    size = struct.unpack('>I', header)[0]
    if size < 1 or size > MAX_FRAME:
        raise ValueError('invalid plist length')
    body = stream.read(size)
    if len(body) != size:
        raise ValueError('truncated plist frame')
    value = plistlib.loads(body)
    if type(value) is not dict or frozenset(value) != PLIST_FIELDS:
        raise ValueError('plist object is not a GetValue response')
    if value['Key'] != key or value['Request'] != 'GetValue':
        raise ValueError('unexpected plist key or request')
    answer = value['Value']
    if type(answer) is not str or not answer:
        raise ValueError('plist value is not a non-empty string')
    return answer


def read_sync_response(data):
    """Two consecutive GetValue frames and nothing else."""
    stream = io.BytesIO(data)
    values = [read_plist_frame(stream, key) for key in SYNC_KEYS]
    if stream.read(1):
        raise ValueError('trailing plist frame')
    return ('sync', values[0], values[1])


def signature(kind, data):
    """Parsed open signature tuple, or None when the wire data is malformed."""
    try:
        if kind == 'tcp':
            if data:
                raise ValueError('TCP open payload must be empty')
            return ('tcp',)
        if kind == 'adb':
            return read_adb_response(data)
        if kind == 'sync':
            return read_sync_response(data)
        raise ValueError('unknown service kind')
    except (ValueError, TypeError, UnicodeError, KeyError, IndexError, OverflowError,
            RecursionError, ArithmeticError, struct.error, ExpatError,
            plistlib.InvalidFileException):
        return None


BAD = object()
_cache = {}


def cached_signature(kind, data):
    """Signatures are pure, so reuse them across snapshots."""
    key = (kind, data)
    found = _cache.get(key, BAD)
    if found is BAD:
        found = _cache[key] = signature(kind, data)
    return found


def probe_script(kind):
    """Return (send, finish) base64 arrays certifying one outbound probe."""
    encode = lambda raw: base64.b64encode(raw).decode('ascii')
    if kind == 'tcp':
        return [], []
    if kind == 'adb':
        return [encode(send_connect())], [encode(send_close())]
    return ([encode(get_value_request(key)) for key in SYNC_KEYS], [])
